"""Explicit batch 18 passage assessments, authored after source/context review."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[2]
def read(p): return json.loads((R/p).read_text(encoding='utf-8'))
def write(p,v): (R/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lib=read('audit/source-notes.json')
def source(key,url,locator,evidence,changing=False,lim='Institutional text inspected; no film or video playback claimed.'):
 lib['sources'][key]=dict(url=url,locator=locator,evidence=evidence,checkedBy='Codex',checkedAt='2026-11-07',timeSensitive=changing,nextReviewAt='2027-02-05' if changing else None,limitations=lim,topics=['Batch 18'])
